 $('recipeIngredients').textContent=unlocked?`Resepi kumpulan: ${required.map(id=>ingredients.find(entry=>entry.id===id)?.name||id).join(' · ')}`:'Jawab kuiz kitaran ini untuk membuka resepi.';
