function showQuestion(q,snap){const order=game.focus,state=cycleQuiz(order);if(state.answered||!q)return;const localRetry=game.retryQuestions.length>0,question=localRetry?game.retryQuestions[0]:q,options=question?.options||question?.choices||{},pairs=Array.isArray(options)?options.map((value,index)=>[['A','B','C','D'][index],value]):Object.entries(options);if(!pairs.length)return;const key=`${order}:${localRetry?'retry:':''}${question.no}`;if(game.questionNo===key)return;game.questionNo=key;game.answering=true;game.currentQuestion=question;game.currentRetry=localRetry;$('quizConnection').textContent=localRetry?'↻ Soalan ulangan kitaran lalu':'● Kuiz kitaran aktif';$('quizQuestion').textContent=question.question||question.text||'Soalan daripada cikgu';$('answers').replaceChildren(...pairs.slice(0,4).map(([letter,text])=>{const button=document.createElement('button');button.type='button';button.textContent=`${letter}. ${text}`;button.onclick=()=>answer(letter,question,snap,localRetry);return button}))}
